, W_SPC_RFC_SAP_PO AS (
SELECT 1  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_SLOC_R                  ') AS TBL_NM, TRIM('XIF_ERP_SLOC_R                  ')+'_SN' AS TBL_SN,  TRIM('ZSD_GSCM_SLOC                ') AS RFC_KEY,  TRIM('PR_SCM_MST_SLOC                                             ') AS PROC_NM, TRIM(N'SLOC Master                      ') AS CALLED_NM UNION
SELECT 2  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_VENDOR_R                ') AS TBL_NM, TRIM('XIF_ERP_VENDOR_R                ')+'_SN' AS TBL_SN,  TRIM('ZMMIF_GSCM_VENDOR            ') AS RFC_KEY,  TRIM('PR_SCM_MST_VENDOR                                           ') AS PROC_NM, TRIM(N'Vendor Master                    ') AS CALLED_NM UNION
SELECT 3  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_CUSTOMER_CONSIGN_STOCK_R') AS TBL_NM, TRIM('XIF_ERP_CUSTOMER_CONSIGN_STOCK_R')+'_SN' AS TBL_SN,  TRIM('ZSDMD_RFC_SCM_CUST_STOCK     ') AS RFC_KEY,  TRIM('PR_SCM_DNM_STOCK_CUSTOMER_CONSIGN,PR_SCM_DNM_SO_STOCK_CUTOFF') AS PROC_NM, TRIM(N'고객 위탁 재고/SO Reserved Stock     ') AS CALLED_NM UNION
SELECT 4  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_INTRANSIT_R             ') AS TBL_NM, TRIM('XIF_ERP_INTRANSIT_R             ')+'_SN' AS TBL_SN,  TRIM('ZLETM_GSCM_INTRANSIT         ') AS RFC_KEY,  TRIM('PR_SCM_DNM_INTRANSIT                                        ') AS PROC_NM, TRIM(N'해상재고 상세                        ') AS CALLED_NM UNION
SELECT 5  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_DELIVERY_TRACKING_R     ') AS TBL_NM, TRIM('XIF_ERP_DELIVERY_TRACKING_R     ')+'_SN' AS TBL_SN,  TRIM('ZLETM_GSCM_DELIVERY_TRACKING ') AS RFC_KEY,  TRIM('PR_SCM_DNM_DELIVERY_TRACKING                                ') AS PROC_NM, TRIM(N'해상재고(GTS) Tracking              ') AS CALLED_NM UNION
SELECT 6  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_MAT_PO_R                ') AS TBL_NM, TRIM('XIF_ERP_MAT_PO_R                ')+'_SN' AS TBL_SN,  TRIM('ZMMIF_GSCM_PO                ') AS RFC_KEY,  TRIM('PR_SCM_DNM_MAT_PO                                           ') AS PROC_NM, TRIM(N'자재 PO                            ') AS CALLED_NM UNION
SELECT 7  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_MAT_PO_RECEIPT_R        ') AS TBL_NM, TRIM('XIF_ERP_MAT_PO_RECEIPT_R        ')+'_SN' AS TBL_SN,  TRIM('ZMMIF_GSCM_PO_RECEIPT        ') AS RFC_KEY,  TRIM('PR_SCM_DNM_MAT_PO_RECEIPT                                   ') AS PROC_NM, TRIM(N'자재 입고 실적                        ') AS CALLED_NM UNION
SELECT 8  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_MAT_INBOUND_DO_R        ') AS TBL_NM, TRIM('XIF_ERP_MAT_INBOUND_DO_R        ')+'_SN' AS TBL_SN,  TRIM('ZMMIF_GSCM_INB_DELIVERY      ') AS RFC_KEY,  TRIM('PR_SCM_DNM_MAT_INBOUND_DO                                   ') AS PROC_NM, TRIM(N'자재 DO 정보                         ') AS CALLED_NM UNION
SELECT 9  SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_MAT_IMPORT_BL_R         ') AS TBL_NM, TRIM('XIF_ERP_MAT_IMPORT_BL_R         ')+'_SN' AS TBL_SN,  TRIM('ZIMX145,ZIMIF_GSCM_IMPORT_BL ') AS RFC_KEY,  TRIM('PR_SCM_DNM_MAT_IMPORT_BL                                    ') AS PROC_NM, TRIM(N'자재 Import BL                      ') AS CALLED_NM UNION
SELECT 10 SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_INTRANSIT_CO_R          ') AS TBL_NM, TRIM('XIF_ERP_INTRANSIT_CO_R          ')+'_SN' AS TBL_SN,  TRIM('ZMMC_RFC_011                 ') AS RFC_KEY,  TRIM('PR_SCM_DNM_INTRANSIT_CO                                     ') AS PROC_NM, TRIM(N'[법인간거래] 전지-> SCP 운송중재고(GI-GR) 전송') AS CALLED_NM UNION
SELECT 11 SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_INTRANSIT_CO_SUMMARY_R  ') AS TBL_NM, TRIM('XIF_ERP_INTRANSIT_CO_SUMMARY_R  ')+'_SN' AS TBL_SN,  TRIM('ZMMC_RFC_011                 ') AS RFC_KEY,  TRIM('PR_SCM_DNM_INTRANSIT_CO                                     ') AS PROC_NM, TRIM(N'[법인간거래] 전지-> SCP 운송중재고(GI-GR) 전송') AS CALLED_NM UNION
