SELECT 14 SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_BEGIN_END_STOCK_R       ') AS TBL_NM, TRIM('XIF_ERP_BEGIN_END_STOCK_R       ')+'_SN' AS TBL_SN,  TRIM('ZPPNV_RFC_ERP_BEGIN_END_STOCK') AS RFC_KEY,  TRIM('NOT_YET                                                     ') AS PROC_NM, TRIM(N'BEGIN_END_STOCK                     ') AS CALLED_NM UNION
SELECT 15 SORT_SEQ, 'SCP' AS MODULE, 'RFC'    AS ITYPE, TRIM('XIF_ERP_ZMM_GSCM_END_STOCK_R    ') AS TBL_NM, TRIM('XIF_ERP_ZMM_GSCM_END_STOCK_R    ')+'_SN' AS TBL_SN,  TRIM('ZMMIF_GSCM_END_STOCK         ') AS RFC_KEY,  TRIM('PR_SCP_ANL_MONTH_END_STOCK_R                                ') AS PROC_NM, TRIM(N'[전지 GSCM] 기말재고/미착재고              ') AS CALLED_NM UNION
SELECT 16 SORT_SEQ, 'SCP' AS MODULE, 'SAP PO' AS ITYPE, TRIM('XIF_MRP_NO_USE_3M_OUT_IF_R      ') AS TBL_NM, TRIM('XIF_MRP_NO_USE_3M_OUT_IF_R      ')+'_SN' AS TBL_SN,  TRIM('NMM0266                      ') AS RFC_KEY,  TRIM('PR_SCP_MST_NO_USE_3M                                        ') AS PROC_NM, TRIM(N'MRP Long term stock No Use 3M Out   ') AS CALLED_NM UNION
SELECT 17 SORT_SEQ, 'SCP' AS MODULE, 'SAP PO' AS ITYPE, TRIM('XIF_MRP_PIC_INFO_OUT_IF_R       ') AS TBL_NM, TRIM('XIF_MRP_PIC_INFO_OUT_IF_R       ')+'_SN' AS TBL_SN,  TRIM('NMM0270                      ') AS RFC_KEY,  TRIM('PR_SCP_MST_PIC_INFO                                         ') AS PROC_NM, TRIM(N'MRP Long term stock PIC Info        ') AS CALLED_NM
)
SELECT 'SPC' RTYPE,ITYPE AS IXTYPE,CASE WHEN ITYPE = 'RFC' THEN (CASE WHEN (SPV.TBL_NM LIKE '%INTRANSIT_CO_SUM%' OR SPV.TBL_NM LIKE '%INTRANSIT_CO_DET%') THEN '' ELSE 'EXEC PR_SCM_SYS_RFC_CALL_NERP '+''''+SPV.TBL_NM+';''' END) ELSE '' END AS EXEC_SCRIPT
      ,CASE WHEN WR.GOT_ROW_TBL IS NOT NULL THEN 'EXIST_GOT_HISTORY' ELSE '' END GOT_STATUS
      ,CASE WHEN SPV.TBL_NM = 'XIF_ERP_INTRANSIT_CO_R' THEN '' 
           ELSE 'SELECT TOP 100 * FROM '+SPV.TBL_SN+' WITH(NOLOCK) WHERE '+ CASE WHEN SPV.ITYPE = 'RFC' THEN 'TRANSFER_DATE = '+''''+FORMAT(GETDATE(),'yyyyMMdd')+'''' 
                                                                                 WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%EDI%' THEN 'TRANSFER_CREATE_DATE = '+''''+FORMAT(GETDATE(),'yyyyMMdd')+'''' 
                                                                                 WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%XIF_CUST_DEMAND_MAPPING_MST_R%' THEN 'TRANSFER_DATE = '+''''+FORMAT(GETDATE(),'yyyyMMdd')+''''  ELSE 'FORMAT(IF_RCV_DATE,''yyyyMMdd'') = '+''''+FORMAT(GETDATE(),'yyyyMMdd')+'''' END END AS GET_DATA
      ,CASE WHEN SPV.PROC_NM = 'NOT_YET' THEN '' ELSE 'EXEC '+SPV.PROC_NM+';' END AS APPLY_EXEC
      ,WOR.CODETYPE
      ,WOR.COLUMN_NAME
      ,CASE WHEN SPV.ITYPE = 'RFC' AND SPV.TBL_NM = 'XIF_ERP_BEGIN_END_STOCK_R' THEN 'FORMAT(TRANSFER_DATE,''yyyyMMdd'')' 
            WHEN SPV.ITYPE = 'RFC' THEN 'TRANSFER_DATE' 
            WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%EDI%' THEN 'TRANSFER_CREATE_DATE'
            WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%XIF_CUST_DEMAND_MAPPING_MST_R%' THEN 'TRANSFER_DATE'  ELSE 'FORMAT(IF_RCV_DATE,''yyyyMMdd'')' END AS TRANSFER_DATE
      ,CASE WHEN SPV.ITYPE = 'RFC' THEN 'TRANSFER_TIME' 
            WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%EDI%' THEN 'TRANSFER_CREATE_TIME'
            WHEN SPV.ITYPE <> 'RFC' AND SPV.TBL_NM LIKE '%XIF_CUST_DEMAND_MAPPING_MST_R%' THEN 'TRANSFER_TIME'  ELSE 'FORMAT(IF_RCV_DATE,''HHmmss'')' END AS TRANSFER_TIME
      ,WOR.MAX_CREATION_DATE
      ,SPV.* 
FROM   W_SPC_RFC_SAP_PO AS SPV WITH(NOLOCK)
LEFT  JOIN   W_RAW AS WR ON CASE WHEN WR.GOT_ROW_TBL = 'XIF_ERP_CUSTOMER_CONSIGN_STOCK' THEN 'XIF_ERP_CUSTOMER_CONSIGN_STOCK_R' ELSE WR.GOT_ROW_TBL END = SPV.TBL_NM
LEFT  JOIN   W_OLD_RAW AS WOR ON LOOKUP_TYPE = SPV.TBL_NM AND WOR.RNUM = 1

